/**
 * Puzzle engine for the "reverse math" games under /games: you are given the answer and have to
 * find what produces it (the numbers, the operators, or the steps).
 *
 * Every puzzle is generated from a seed, so "Level 12" or "the daily puzzle for 2026-11-25" is the
 * same for every player, and generated by building a real solution first. Each game also has a
 * solver; scripts/test-reverse-math.ts runs the solvers over thousands of seeds to prove that every
 * level is solvable. Pure TypeScript, no DOM, so the tests run under plain Node.
 */

export type Op = '+' | '-' | '*' | '/';
export const OPS: Op[] = ['+', '-', '*', '/'];
/** Display glyphs: a real minus and times sign read better than ASCII at large sizes. */
export const OP_GLYPH: Record<Op, string> = { '+': '+', '-': '−', '*': '×', '/': '÷' };

// ---------------------------------------------------------------- seeded randomness

export type Rng = () => number;

/** mulberry32: tiny, fast and good enough for puzzle generation. */
export function rngFromSeed(seed: string): Rng {
  let h = 1779033703 ^ seed.length;
  for (let i = 0; i < seed.length; i++) {
    h = Math.imul(h ^ seed.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  let a = h >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export const randInt = (rng: Rng, lo: number, hi: number) => lo + Math.floor(rng() * (hi - lo + 1));
export const pick = <T,>(rng: Rng, list: readonly T[]) => list[Math.floor(rng() * list.length)];
export function shuffled<T>(rng: Rng, list: readonly T[]): T[] {
  const out = [...list];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

/** Local calendar date (y-m-d), never 24h arithmetic, so DST days do not break streaks. */
export function localDateKey(d = new Date()) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
export function previousDateKey(key: string) {
  const [y, m, d] = key.split('-').map(Number);
  return localDateKey(new Date(y, m - 1, d - 1));
}

// ---------------------------------------------------------------- expression evaluation

/**
 * Evaluates n0 op0 n1 op1 n2 ... with normal precedence (× and ÷ before + and −, left to right).
 * Returns null if a division is by zero or not exact, so every puzzle stays in whole numbers.
 */
export function evaluate(nums: readonly number[], ops: readonly Op[]): number | null {
  if (nums.length !== ops.length + 1) return null;
  let total = 0;
  let sign = 1;
  let term = nums[0];
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    const n = nums[i + 1];
    if (op === '*') term *= n;
    else if (op === '/') {
      if (n === 0 || term % n !== 0) return null;
      term /= n;
    } else {
      total += sign * term;
      sign = op === '+' ? 1 : -1;
      term = n;
    }
  }
  return total + sign * term;
}

export const formatExpr = (nums: readonly (number | string)[], ops: readonly Op[]) =>
  nums.map((n, i) => (i < ops.length ? `${n} ${OP_GLYPH[ops[i]]} ` : `${n}`)).join('');

// ---------------------------------------------------------------- game 1: Fill the Equation
// A fixed operator row and a target; place the number tiles into the blanks.

export interface FillPuzzle {
  ops: Op[];
  target: number;
  /** Tiles shown to the player (includes decoys at higher levels), sorted ascending. */
  tiles: number[];
  /** One known solution: tile values in slot order. */
  solution: number[];
  tier: string;
}

interface FillTier {
  name: string;
  slots: number;
  ops: Op[];
  max: number;
  decoys: number;
  /** Reject puzzles with more distinct solutions than this, so higher tiers need real thought. */
  maxSolutions: number;
}

export function fillTier(level: number): FillTier {
  if (level <= 5) return { name: 'Warm-up', slots: 3, ops: ['+', '-'], max: 9, decoys: 0, maxSolutions: 99 };
  if (level <= 15) return { name: 'Easy', slots: 3, ops: ['+', '-', '*'], max: 9, decoys: 0, maxSolutions: 6 };
  if (level <= 30) return { name: 'Medium', slots: 4, ops: ['+', '-', '*'], max: 12, decoys: 0, maxSolutions: 8 };
  if (level <= 50) return { name: 'Hard', slots: 4, ops: ['+', '-', '*', '/'], max: 12, decoys: 1, maxSolutions: 4 };
  return { name: 'Expert', slots: 5, ops: ['+', '-', '*', '/'], max: 15, decoys: 2, maxSolutions: 4 };
}

/** All tile assignments (as value lists in slot order) that hit the target, up to `limit`. */
export function solveFill(ops: readonly Op[], tiles: readonly number[], target: number, limit = 1000): number[][] {
  const found: number[][] = [];
  const seen = new Set<string>();
  const used = new Array(tiles.length).fill(false);
  const chosen: number[] = [];
  const slots = ops.length + 1;
  const walk = () => {
    if (found.length >= limit) return;
    if (chosen.length === slots) {
      if (evaluate(chosen, ops) === target) {
        const key = chosen.join(',');
        if (!seen.has(key)) {
          seen.add(key);
          found.push([...chosen]);
        }
      }
      return;
    }
    for (let i = 0; i < tiles.length; i++) {
      if (used[i]) continue;
      used[i] = true;
      chosen.push(tiles[i]);
      walk();
      chosen.pop();
      used[i] = false;
    }
  };
  walk();
  return found;
}

export function generateFill(seed: string, level: number): FillPuzzle {
  const tier = fillTier(level);
  const rng = rngFromSeed(`fill|${seed}`);
  for (let attempt = 0; attempt < 4000; attempt++) {
    const pool = shuffled(rng, Array.from({ length: tier.max - 1 }, (_, i) => i + 2)); // 2..max, no 1s
    const solution = pool.slice(0, tier.slots);
    const ops = Array.from({ length: tier.slots - 1 }, () => pick(rng, tier.ops));
    // Higher tiers must actually use the harder operators they introduce.
    if (tier.ops.includes('*') && level > 5 && !ops.includes('*') && !ops.includes('/')) continue;
    if (tier.ops.includes('/') && attempt < 2000 && !ops.includes('/')) continue;
    const target = evaluate(solution, ops);
    if (target === null || target < 1 || target > 160) continue;
    const decoys = pool.slice(tier.slots, tier.slots + tier.decoys);
    const tiles = [...solution, ...decoys].sort((a, b) => a - b);
    const count = solveFill(ops, tiles, target, tier.maxSolutions + 1).length;
    if (count === 0 || count > tier.maxSolutions) continue;
    return { ops, target, tiles, solution, tier: tier.name };
  }
  // Unreachable in practice (tests generate thousands of levels); a safe, solvable fallback.
  return { ops: ['+', '-'], target: 7, tiles: [2, 4, 9], solution: [2, 9, 4], tier: tier.name };
}

// ---------------------------------------------------------------- game 2: Missing Operators
// The numbers and the answer are fixed; choose the operators between them.

export interface OpsPuzzle {
  nums: number[];
  target: number;
  solution: Op[];
  allowed: Op[];
  tier: string;
}

export function opsTier(level: number) {
  if (level <= 6) return { name: 'Warm-up', count: 3, allowed: ['+', '-', '*'] as Op[], max: 9, maxSolutions: 2 };
  if (level <= 20) return { name: 'Easy', count: 4, allowed: ['+', '-', '*'] as Op[], max: 9, maxSolutions: 2 };
  if (level <= 40) return { name: 'Medium', count: 4, allowed: OPS, max: 12, maxSolutions: 2 };
  if (level <= 70) return { name: 'Hard', count: 5, allowed: OPS, max: 12, maxSolutions: 2 };
  return { name: 'Expert', count: 6, allowed: OPS, max: 15, maxSolutions: 1 };
}

export function solveOps(nums: readonly number[], target: number, allowed: readonly Op[] = OPS, limit = 1000): Op[][] {
  const found: Op[][] = [];
  const ops: Op[] = [];
  const walk = () => {
    if (found.length >= limit) return;
    if (ops.length === nums.length - 1) {
      if (evaluate(nums, ops) === target) found.push([...ops]);
      return;
    }
    for (const op of allowed) {
      ops.push(op);
      walk();
      ops.pop();
    }
  };
  walk();
  return found;
}

export function generateOps(seed: string, level: number): OpsPuzzle {
  const tier = opsTier(level);
  const rng = rngFromSeed(`ops|${seed}`);
  for (let attempt = 0; attempt < 4000; attempt++) {
    const nums = Array.from({ length: tier.count }, () => randInt(rng, 2, tier.max));
    const solution = Array.from({ length: tier.count - 1 }, () => pick(rng, tier.allowed));
    if (new Set(solution).size < Math.min(2, solution.length)) continue; // at least two kinds of op
    if (tier.allowed.includes('/') && attempt < 2500 && !solution.includes('/')) continue;
    const target = evaluate(nums, solution);
    if (target === null || target < 0 || target > 400) continue;
    const count = solveOps(nums, target, tier.allowed, tier.maxSolutions + 1).length;
    if (count === 0 || count > tier.maxSolutions) continue;
    return { nums, target, solution, allowed: tier.allowed, tier: tier.name };
  }
  return { nums: [3, 4, 2], target: 14, solution: ['*', '+'], allowed: tier.allowed, tier: tier.name };
}

// ---------------------------------------------------------------- game 3: Number Target
// Combine the numbers two at a time with + − × ÷ until one number is left, and make it the target.

export interface Step {
  a: number;
  op: Op;
  b: number;
  result: number;
}

export interface TargetPuzzle {
  nums: number[];
  target: number;
  /** One known route. */
  solution: Step[];
  tier: string;
}

/** Result of a single combine step, or null when the step is not allowed (negative, fraction, ÷0). */
export function combine(a: number, op: Op, b: number): number | null {
  if (op === '+') return a + b;
  if (op === '-') return a - b >= 0 ? a - b : null;
  if (op === '*') return a * b;
  if (b === 0 || a % b !== 0) return null;
  return a / b;
}

/** Depth-first search for a route that uses every number. Returns null when none exists. */
export function solveTarget(nums: readonly number[], target: number): Step[] | null {
  const steps: Step[] = [];
  const seen = new Set<string>();
  const walk = (list: number[]): boolean => {
    if (list.length === 1) return list[0] === target;
    const key = [...list].sort((x, y) => x - y).join(',');
    if (seen.has(key)) return false;
    seen.add(key);
    for (let i = 0; i < list.length; i++) {
      for (let j = 0; j < list.length; j++) {
        if (i === j) continue;
        for (const op of OPS) {
          if ((op === '+' || op === '*') && j < i) continue; // commutative: try each pair once
          const r = combine(list[i], op, list[j]);
          if (r === null) continue;
          const rest = list.filter((_, k) => k !== i && k !== j);
          rest.push(r);
          steps.push({ a: list[i], op, b: list[j], result: r });
          if (walk(rest)) return true;
          steps.pop();
        }
      }
    }
    return false;
  };
  return walk([...nums]) ? steps : null;
}

/** Every value reachable by combining all numbers (used to keep targets from being trivial). */
function reachableTargets(nums: readonly number[]): Set<number> {
  const out = new Set<number>();
  const seen = new Set<string>();
  const walk = (list: number[]) => {
    const key = [...list].sort((x, y) => x - y).join(',');
    if (seen.has(key)) return;
    seen.add(key);
    if (list.length === 1) {
      out.add(list[0]);
      return;
    }
    for (let i = 0; i < list.length; i++)
      for (let j = 0; j < list.length; j++) {
        if (i === j) continue;
        for (const op of OPS) {
          const r = combine(list[i], op, list[j]);
          if (r === null) continue;
          walk([...list.filter((_, k) => k !== i && k !== j), r]);
        }
      }
  };
  walk([...nums]);
  return out;
}

export function targetTier(level: number) {
  if (level <= 8) return { name: 'Warm-up', count: 3, max: 9, lo: 10, hi: 40 };
  if (level <= 25) return { name: 'Easy', count: 4, max: 9, lo: 12, hi: 60 };
  if (level <= 50) return { name: 'Medium', count: 4, max: 13, lo: 20, hi: 120 };
  if (level <= 80) return { name: 'Hard', count: 5, max: 13, lo: 40, hi: 250 };
  return { name: 'Expert', count: 6, max: 15, lo: 100, hi: 500 };
}

export function generateTarget(seed: string, level: number): TargetPuzzle {
  const tier = targetTier(level);
  const rng = rngFromSeed(`target|${seed}`);
  for (let attempt = 0; attempt < 400; attempt++) {
    const nums = Array.from({ length: tier.count }, () => randInt(rng, 1, tier.max));
    const reach = [...reachableTargets(nums)].filter((t) => t >= tier.lo && t <= tier.hi && !nums.includes(t));
    if (reach.length === 0) continue;
    const target = pick(rng, reach);
    const solution = solveTarget(nums, target);
    if (!solution) continue;
    return { nums, target, solution, tier: tier.name };
  }
  return { nums: [3, 4, 5], target: 35, solution: solveTarget([3, 4, 5], 35)!, tier: tier.name };
}

/** Classic "make 24" daily: four numbers 1-13 that can make 24, chosen by date. */
export function generateDaily24(seed: string): TargetPuzzle {
  const rng = rngFromSeed(`24|${seed}`);
  for (;;) {
    const nums = Array.from({ length: 4 }, () => randInt(rng, 1, 13));
    const solution = solveTarget(nums, 24);
    // Skip sets that are a one-liner (24 already present, or plain sum).
    if (!solution || nums.includes(24) || nums.reduce((s, n) => s + n, 0) === 24) continue;
    return { nums, target: 24, solution, tier: 'Daily 24' };
  }
}

// ---------------------------------------------------------------- game 4: Cross Sums (math crossword)
// Equations "a op b = c" cross each other on a grid; some numbers are blank, fill them from a tray.

export type CrossCell =
  | { kind: 'num'; value: number; blank: boolean }
  | { kind: 'op'; op: Op }
  | { kind: 'eq' };

export interface CrossEquation {
  /** Cell keys "r,c" for [a, op, b, =, c]. */
  cells: string[];
  dir: 'h' | 'v';
}

export interface CrossPuzzle {
  rows: number;
  cols: number;
  cells: Record<string, CrossCell>;
  equations: CrossEquation[];
  /** Keys of blank number cells, reading order. */
  blanks: string[];
  /** Values to place, sorted ascending (one tile per blank). */
  tray: number[];
  tier: string;
}

export function crossTier(level: number) {
  if (level <= 5) return { name: 'Warm-up', eqs: 3, ops: ['+', '-'] as Op[], max: 20, blankRate: 0.45, size: 7 };
  if (level <= 15) return { name: 'Easy', eqs: 4, ops: ['+', '-', '*'] as Op[], max: 30, blankRate: 0.4, size: 9 };
  if (level <= 35) return { name: 'Medium', eqs: 5, ops: OPS, max: 50, blankRate: 0.45, size: 9 };
  if (level <= 60) return { name: 'Hard', eqs: 6, ops: OPS, max: 80, blankRate: 0.55, size: 9 };
  return { name: 'Expert', eqs: 7, ops: OPS, max: 99, blankRate: 0.62, size: 9 };
}

const key = (r: number, c: number) => `${r},${c}`;

/** Builds a, b, c for "a op b = c" with the number at `fixedIndex` (0 = a, 1 = b, 2 = c) set. */
function equationValues(rng: Rng, op: Op, fixedIndex: number, v: number, max: number): [number, number, number] | null {
  const small = () => randInt(rng, 2, 9);
  const any = () => randInt(rng, 1, Math.min(max, 20));
  const ok = (t: [number, number, number]) => (t.every((n) => Number.isInteger(n) && n >= 1 && n <= max) ? t : null);
  if (fixedIndex === 0) {
    if (op === '+') { const b = any(); return ok([v, b, v + b]); }
    if (op === '-') { if (v < 2) return null; const b = randInt(rng, 1, v - 1); return ok([v, b, v - b]); }
    if (op === '*') { const b = small(); return ok([v, b, v * b]); }
    const ds = divisors(v).filter((d) => d > 1 && d < v);
    if (!ds.length) return null;
    const b = pick(rng, ds);
    return ok([v, b, v / b]);
  }
  if (fixedIndex === 1) {
    if (op === '+') { const a = any(); return ok([a, v, a + v]); }
    if (op === '-') { const c = any(); return ok([v + c, v, c]); }
    if (op === '*') { const a = small(); return ok([a, v, a * v]); }
    if (v < 2) return null;
    const c = small();
    return ok([v * c, v, c]);
  }
  if (op === '+') { if (v < 2) return null; const a = randInt(rng, 1, v - 1); return ok([a, v - a, v]); }
  if (op === '-') { const b = any(); return ok([v + b, b, v]); }
  if (op === '*') {
    const ds = divisors(v).filter((d) => d > 1 && d < v);
    if (!ds.length) return null;
    const a = pick(rng, ds);
    return ok([a, v / a, v]);
  }
  const b = small();
  return ok([v * b, b, v]);
}

function divisors(n: number) {
  const out: number[] = [];
  for (let d = 1; d <= n; d++) if (n % d === 0) out.push(d);
  return out;
}

export function checkEquation(values: readonly (number | null)[], op: Op): boolean | null {
  const [a, b, c] = values;
  if (a == null || b == null || c == null) return null;
  const r = combine(a, op, b);
  return r !== null && r === c && (op !== '-' || a - b >= 0);
}

export function generateCross(seed: string, level: number): CrossPuzzle {
  const tier = crossTier(level);
  const rng = rngFromSeed(`cross|${seed}`);
  for (let attempt = 0; attempt < 500; attempt++) {
    const p = tryBuildCross(rng, tier);
    if (p) return { ...p, tier: tier.name };
  }
  throw new Error('cross: generation failed'); // tests guarantee this never happens for real seeds
}

function tryBuildCross(rng: Rng, tier: ReturnType<typeof crossTier>): Omit<CrossPuzzle, 'tier'> | null {
  const cells = new Map<string, CrossCell>();
  const owner = new Map<string, number>(); // how many equations use a number cell
  const equations: CrossEquation[] = [];
  const LIMIT = tier.size; // final bounding box must fit LIMIT x LIMIT

  const place = (r0: number, c0: number, dir: 'h' | 'v', vals: [number, number, number], op: Op) => {
    const keys: string[] = [];
    for (let i = 0; i < 5; i++) {
      const r = dir === 'v' ? r0 + i : r0;
      const c = dir === 'h' ? c0 + i : c0;
      const k = key(r, c);
      keys.push(k);
      if (i % 2 === 0) {
        if (!cells.has(k)) cells.set(k, { kind: 'num', value: vals[i / 2], blank: false });
        owner.set(k, (owner.get(k) ?? 0) + 1);
      } else cells.set(k, i === 1 ? { kind: 'op', op } : { kind: 'eq' });
    }
    equations.push({ cells: keys, dir });
  };

  const bounds = () => {
    let r0 = Infinity, r1 = -Infinity, c0 = Infinity, c1 = -Infinity;
    for (const k of cells.keys()) {
      const [r, c] = k.split(',').map(Number);
      r0 = Math.min(r0, r); r1 = Math.max(r1, r); c0 = Math.min(c0, c); c1 = Math.max(c1, c);
    }
    return { r0, r1, c0, c1 };
  };

  // First equation, horizontal at the origin.
  {
    const op = pick(rng, tier.ops);
    const vals = equationValues(rng, op, 0, randInt(rng, 2, Math.min(tier.max, 20)), tier.max);
    if (!vals) return null;
    place(0, 0, 'h', vals, op);
  }

  let guard = 0;
  while (equations.length < tier.eqs && guard++ < 300) {
    // Cross an existing number cell that only one equation uses, in the other direction.
    const anchors = [...cells.entries()].filter(([k, c]) => c.kind === 'num' && owner.get(k) === 1);
    if (!anchors.length) return null;
    const [ak, acell] = pick(rng, anchors);
    const parent = equations.find((e) => e.cells.includes(ak))!;
    const dir = parent.dir === 'h' ? 'v' : 'h';
    const index = pick(rng, [0, 1, 2]); // position of the anchor inside the new equation
    const [ar, ac] = ak.split(',').map(Number);
    const r0 = dir === 'v' ? ar - index * 2 : ar;
    const c0 = dir === 'h' ? ac - index * 2 : ac;

    // Crossword rule: the new line may only touch the grid at the anchor.
    let fits = true;
    for (let i = -1; i <= 5 && fits; i++) {
      const r = dir === 'v' ? r0 + i : r0;
      const c = dir === 'h' ? c0 + i : c0;
      const k = key(r, c);
      if (k === ak) continue;
      if (i === -1 || i === 5) { if (cells.has(k)) fits = false; continue; }
      if (cells.has(k)) { fits = false; continue; }
      const side = dir === 'h' ? [key(r - 1, c), key(r + 1, c)] : [key(r, c - 1), key(r, c + 1)];
      if (side.some((s) => cells.has(s))) fits = false;
    }
    if (!fits) continue;

    const op = pick(rng, tier.ops);
    const vals = equationValues(rng, op, index, (acell as { value: number }).value, tier.max);
    if (!vals) continue;
    place(r0, c0, dir, vals, op);
    const b = bounds();
    if (b.r1 - b.r0 + 1 > LIMIT || b.c1 - b.c0 + 1 > LIMIT) {
      // Undo the last placement.
      const e = equations.pop()!;
      e.cells.forEach((k, i) => {
        if (k === ak) { owner.set(k, 1); return; }
        if (i % 2 === 0) owner.delete(k);
        cells.delete(k);
      });
    }
  }
  if (equations.length < tier.eqs) return null;

  // Normalise to a 0-based grid.
  const { r0, r1, c0, c1 } = bounds();
  const norm = (k: string) => {
    const [r, c] = k.split(',').map(Number);
    return key(r - r0, c - c0);
  };
  const outCells: Record<string, CrossCell> = {};
  for (const [k, c] of cells) outCells[norm(k)] = c;
  const outEqs = equations.map((e) => ({ dir: e.dir, cells: e.cells.map(norm) }));

  // Blank a share of the numbers, crossings first-class: keep at least one given number per equation
  // on easy tiers so the player always has a foothold.
  const numKeys = Object.keys(outCells)
    .filter((k) => outCells[k].kind === 'num')
    .sort((a, b) => {
      const [ar, ac] = a.split(',').map(Number);
      const [br, bc] = b.split(',').map(Number);
      return ar - br || ac - bc;
    });
  const target = Math.max(2, Math.round(numKeys.length * tier.blankRate));
  const order = shuffled(rng, numKeys);
  const blankSet = new Set<string>();
  for (const k of order) {
    if (blankSet.size >= target) break;
    blankSet.add(k);
    // Never blank a whole equation.
    const full = outEqs.some((e) => [0, 2, 4].every((i) => blankSet.has(e.cells[i])));
    if (full) blankSet.delete(k);
  }
  if (blankSet.size < 2) return null;
  const blanks = numKeys.filter((k) => blankSet.has(k));
  for (const k of blanks) (outCells[k] as { blank: boolean }).blank = true;
  const tray = blanks.map((k) => (outCells[k] as { value: number }).value).sort((a, b) => a - b);
  return { rows: r1 - r0 + 1, cols: c1 - c0 + 1, cells: outCells, equations: outEqs, blanks, tray };
}

/** Checks a full fill (blank key -> value): every equation holds. */
export function crossSolved(p: CrossPuzzle, fill: Record<string, number | null>): boolean {
  return p.equations.every((e) => {
    const vals = [0, 2, 4].map((i) => {
      const cell = p.cells[e.cells[i]] as { value: number; blank: boolean };
      return cell.blank ? fill[e.cells[i]] ?? null : cell.value;
    });
    const op = (p.cells[e.cells[1]] as { op: Op }).op;
    return checkEquation(vals, op) === true;
  });
}

/** Backtracking solver over the tray (independent of the stored values). Returns one fill or null. */
export function solveCross(p: CrossPuzzle): Record<string, number> | null {
  const fill: Record<string, number | null> = {};
  const used = new Array(p.tray.length).fill(false);
  const eqsOf = (k: string) => p.equations.filter((e) => e.cells.includes(k));
  const partialOk = (k: string) =>
    eqsOf(k).every((e) => {
      const vals = [0, 2, 4].map((i) => {
        const cell = p.cells[e.cells[i]] as { value: number; blank: boolean };
        return cell.blank ? fill[e.cells[i]] ?? null : cell.value;
      });
      const ok = checkEquation(vals, (p.cells[e.cells[1]] as { op: Op }).op);
      return ok !== false;
    });
  const walk = (i: number): boolean => {
    if (i === p.blanks.length) return crossSolved(p, fill);
    const k = p.blanks[i];
    const tried = new Set<number>();
    for (let t = 0; t < p.tray.length; t++) {
      if (used[t] || tried.has(p.tray[t])) continue;
      tried.add(p.tray[t]);
      used[t] = true;
      fill[k] = p.tray[t];
      if (partialOk(k) && walk(i + 1)) return true;
      fill[k] = null;
      used[t] = false;
    }
    return false;
  };
  return walk(0) ? (fill as Record<string, number>) : null;
}

// ---------------------------------------------------------------- canonical forms and level curve
// Canonical strings decide when two puzzles are "the same" for the no-repeat history.

/**
 * Level used for generation. The curve rises with the level number; after level 100 it varies
 * between the harder tiers instead of staying flat; and if a player has exhausted a small space (many
 * retries), it moves on in difficulty rather than repeating.
 */
export function effectiveLevel(level: number, attempt: number, seed: string): number {
  let l = level + Math.floor(attempt / 30) * 6;
  if (l > 100) l = 31 + Math.floor(rngFromSeed(`lvl|${seed}`)() * 90);
  return l;
}

/** Fill: same target, same tiles, same signed term shapes in any order = same puzzle. */
export function canonFill(p: FillPuzzle): string {
  const terms: string[] = [];
  let cur = '+';
  for (const op of p.ops) {
    if (op === '*' || op === '/') cur += op;
    else {
      terms.push(cur);
      cur = op;
    }
  }
  terms.push(cur);
  return `F|${p.target}|${p.tiles.join(',')}|${terms.sort().join(' ')}`;
}

export const canonOps = (p: OpsPuzzle) => `O|${p.target}|${p.nums.join(',')}|${p.allowed.join('')}`;

export const canonTarget = (p: TargetPuzzle) => `T|${p.target}|${[...p.nums].sort((a, b) => a - b).join(',')}`;

/** Cross: the set of equations (values, operator, which numbers are blank); layout and order ignored. */
export function canonCross(p: CrossPuzzle): string {
  const eqs = p.equations.map((e) => {
    const n = (i: number) => {
      const c = p.cells[e.cells[i]] as { value: number; blank: boolean };
      return `${c.blank ? '?' : ''}${c.value}`;
    };
    return `${n(0)}${(p.cells[e.cells[1]] as { op: Op }).op}${n(2)}=${n(4)}`;
  });
  return `C|${eqs.sort().join(';')}`;
}
